/**
 * REST API Client — Typed HTTP methods with error handling.
 */

class ApiManager {
    constructor(baseUrl = 'http://localhost:8000') {
        this.baseUrl = baseUrl.replace(/\/+$/, '');
    }

    /**
     * Update the base URL.
     */
    setBaseUrl(url) {
        this.baseUrl = url.replace(/\/+$/, '');
    }

    /**
     * GET request.
     * @param {string} path - e.g. '/api/overview'
     * @param {object} [params] - query parameters
     * @param {number} [timeout] - request timeout in ms (default: 10000)
     * @returns {Promise<any>}
     */
    async get(path, params = {}, timeout = 10000) {
        const url = this._buildUrl(path, params);
        const controller = new AbortController();
        const timer = setTimeout(() => controller.abort(), timeout);
        try {
            const res = await fetch(url, {
                method: 'GET',
                headers: this._headers(),
                signal: controller.signal,
            });
            return await this._handleResponse(res);
        } finally {
            clearTimeout(timer);
        }
    }

    /**
     * POST request.
     * @param {string} path
     * @param {object} [body]
     * @returns {Promise<any>}
     */
    async post(path, body = {}) {
        const url = this._buildUrl(path);
        const res = await fetch(url, {
            method: 'POST',
            headers: this._headers(),
            body: JSON.stringify(body),
        });
        return this._handleResponse(res);
    }

    /**
     * PATCH request.
     * @param {string} path
     * @param {object} [body]
     * @returns {Promise<any>}
     */
    async patch(path, body = {}) {
        const url = this._buildUrl(path);
        const res = await fetch(url, {
            method: 'PATCH',
            headers: this._headers(),
            body: JSON.stringify(body),
        });
        return this._handleResponse(res);
    }

    /**
     * DELETE request.
     * @param {string} path
     * @returns {Promise<any>}
     */
    async delete(path) {
        const url = this._buildUrl(path);
        const res = await fetch(url, {
            method: 'DELETE',
            headers: this._headers(),
        });
        return this._handleResponse(res);
    }

    // ==========================================================
    // Domain Methods
    // ==========================================================

    /** GET /api/overview — dashboard overview data */
    async getOverview() {
        return this.get('/api/overview');
    }

    /** GET /api/sessions — list flight sessions */
    async getSessions(params = {}) {
        return this.get('/api/sessions', params);
    }

    /** GET /api/telemetry — current telemetry snapshot */
    async getTelemetry() {
        return this.get('/api/telemetry');
    }

    /** GET /api/conversations — chat history */
