        home: { x: 0, y: 0, z: 0 },
    },

    // Environment
    environment: {
        id: null,
        temperature: 25,
        humidity: 60,
        windSpeed: 0,
        windDirection: 0,
        pressure: 1013,
        location: '',
        description: '',
