        return this.container?.querySelector(`#${id}`)?.value || '';
    }

    _getSelectVal(id) {
        return this.container?.querySelector(`#${id}`)?.value || '';
    }

    _getConfigPreview() {
        try {
            const saved = JSON.parse(localStorage.getItem('flight-control-config') || '{}');
