    }

    _updateJsonPreview() {
        const el = this.container?.querySelector('#cfg-json-preview');
        if (el) el.value = this._getConfigPreview();
    }

    _escAttr(str) {
        return String(str || '').replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    }
}

